query AdevPreflight($projectOwner: String!, $projectNumber: Int!, $isOrg: Boolean!, $repoOwner: String!, $repoName: String!) {
  organization(login: $projectOwner) @include(if: $isOrg) {
    projectV2(number: $projectNumber) { ...AdevPreflightProject }
  }
  user(login: $projectOwner) @skip(if: $isOrg) {
    projectV2(number: $projectNumber) { ...AdevPreflightProject }
  }
  repository(owner: $repoOwner, name: $repoName) {
    id
    nameWithOwner
    visibility
  }
}

fragment AdevPreflightProject on ProjectV2 {
  id
  title
  public
  fields(first: 100) {
    totalCount
    nodes {
      ... on ProjectV2FieldCommon { id name dataType }
      ... on ProjectV2SingleSelectField { options { id name } }
    }
  }
}

mutation CreateIssue($repositoryId: ID!, $title: String!, $body: String!) {
  createIssue(input: { repositoryId: $repositoryId, title: $title, body: $body }) {
    issue { id number }
  }
}

mutation AddToProject($projectId: ID!, $contentId: ID!) {
  addProjectV2ItemById(input: { projectId: $projectId, contentId: $contentId }) {
    item { id }
  }
}

mutation SetFields($projectId: ID!, $itemId: ID!, $f0Field: ID!, $f0Value: String!) {
  f0: updateProjectV2ItemFieldValue(input: { projectId: $projectId, itemId: $itemId, fieldId: $f0Field, value: { singleSelectOptionId: $f0Value } }) { clientMutationId }
}

query ProjectItem($itemId: ID!) {
  node(id: $itemId) {
    ... on ProjectV2Item {
      id
          type
          fieldValues(first: 50) {
            nodes {
              __typename
              ... on ProjectV2ItemFieldTextValue { text field { ... on ProjectV2FieldCommon { name } } }
              ... on ProjectV2ItemFieldSingleSelectValue { name field { ... on ProjectV2FieldCommon { name } } }
              ... on ProjectV2ItemFieldNumberValue { number field { ... on ProjectV2FieldCommon { name } } }
            }
          }
          content {
            __typename
            ... on Issue {
              id
              number
              title
              body
              state
              url
              createdAt
              updatedAt
              repository { name owner { login } issueTypes(first: 1) { totalCount } }
              issueType { name }
              labels(first: 100) { totalCount nodes { name } }
              milestone { title }
              parent { number state repository { name owner { login } } }
              blockedBy(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { number state repository { name owner { login } } } }
              subIssues(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { number state repository { name owner { login } } } }
            }
          }
    }
  }
}

query IssueProjectItems($owner: String!, $name: String!, $number: Int!, $after: String) {
  repository(owner: $owner, name: $name) {
    issue(number: $number) {
      projectItems(first: 100, after: $after, includeArchived: false) {
        totalCount
        pageInfo { hasNextPage endCursor }
        nodes {
          project { id }
          id
          type
          fieldValues(first: 50) {
            nodes {
              __typename
              ... on ProjectV2ItemFieldTextValue { text field { ... on ProjectV2FieldCommon { name } } }
              ... on ProjectV2ItemFieldSingleSelectValue { name field { ... on ProjectV2FieldCommon { name } } }
              ... on ProjectV2ItemFieldNumberValue { number field { ... on ProjectV2FieldCommon { name } } }
            }
          }
          content {
            __typename
            ... on Issue {
              id
              number
              title
              body
              state
              url
              createdAt
              updatedAt
              repository { name owner { login } issueTypes(first: 1) { totalCount } }
              issueType { name }
              labels(first: 100) { totalCount nodes { name } }
              milestone { title }
              parent { number state repository { name owner { login } } }
              blockedBy(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { number state repository { name owner { login } } } }
              subIssues(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { number state repository { name owner { login } } } }
            }
          }
        }
      }
    }
  }
}

query ProjectItems($projectId: ID!, $after: String) {
  node(id: $projectId) {
    ... on ProjectV2 {
      items(first: 100, after: $after) {
        totalCount
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          type
          fieldValues(first: 50) {
            nodes {
              __typename
              ... on ProjectV2ItemFieldTextValue { text field { ... on ProjectV2FieldCommon { name } } }
              ... on ProjectV2ItemFieldSingleSelectValue { name field { ... on ProjectV2FieldCommon { name } } }
              ... on ProjectV2ItemFieldNumberValue { number field { ... on ProjectV2FieldCommon { name } } }
            }
          }
          content {
            __typename
            ... on Issue {
              id
              number
              title
              body
              state
              url
              createdAt
              updatedAt
              repository { name owner { login } issueTypes(first: 1) { totalCount } }
              issueType { name }
              labels(first: 100) { totalCount nodes { name } }
              milestone { title }
              parent { number state repository { name owner { login } } }
              blockedBy(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { number state repository { name owner { login } } } }
              subIssues(first: 100) { totalCount pageInfo { hasNextPage endCursor } nodes { number state repository { name owner { login } } } }
            }
          }
        }
      }
    }
  }
}

mutation SetFields($projectId: ID!, $itemId: ID!, $f0Field: ID!, $f0Value: String!) {
  f0: updateProjectV2ItemFieldValue(input: { projectId: $projectId, itemId: $itemId, fieldId: $f0Field, value: { singleSelectOptionId: $f0Value } }) { clientMutationId }
}

mutation CloseIssue($issueId: ID!) {
  closeIssue(input: { issueId: $issueId, stateReason: COMPLETED }) { clientMutationId }
}

mutation AddComment($subjectId: ID!, $body: String!) {
  addComment(input: { subjectId: $subjectId, body: $body }) { clientMutationId }
}
